"""
Embedding provider for Sonorus Cognis memory.

The module and class keep their original Cognis names for import compatibility,
while supporting Sonorus's provider-aware embedding routes.
"""

import hashlib
import logging
import math
import os
import threading
from typing import List

from cognis.embeddings.base import BaseEmbedder, EmbeddingResult
from cognis.utils import LRUCache

logger = logging.getLogger(__name__)


def _truncate_pad_and_normalize(vec: List[float], dim: int) -> List[float]:
    values = [float(x) for x in vec[:dim]]
    if len(values) < dim:
        values.extend([0.0] * (dim - len(values)))
    norm = math.sqrt(sum(x * x for x in values))
    if norm > 0:
        return [x / norm for x in values]
    return values


class OpenAICompatibleEmbedder(BaseEmbedder):
    """Embedding client backed by Sonorus's active LLM provider."""

    def __init__(
        self,
        api_key: str = None,
        model: str = "text-embedding-3-small",
        full_dim: int = 768,
        small_dim: int = 256,
    ):
        self._api_key = api_key
        self._model = model
        self._full_dim = full_dim
        self._small_dim = small_dim
        self._cache = LRUCache(max_size=500, ttl_seconds=3600)
        self._cache_lock = threading.RLock()

    def _cache_key(self, text: str) -> str:
        digest = hashlib.sha256(str(text).encode("utf-8")).hexdigest()
        return f"emb:{self._full_dim}:{self._small_dim}:{digest}"

    def _result_from_vector(self, vector: List[float]) -> EmbeddingResult:
        full_vec = _truncate_pad_and_normalize(vector, self._full_dim)
        small_vec = _truncate_pad_and_normalize(full_vec, self._small_dim)
        return EmbeddingResult(embeddings={
            self._full_dim: full_vec,
            self._small_dim: small_vec,
        })

    def _load_provider_settings(self):
        try:
            from utils.settings import load_settings
            settings = load_settings()
            return settings.get("llm", {}) or {}, settings.get("memory", {}) or {}
        except Exception:
            return {}, {}

    def _get_key(self, llm_settings: dict, provider: str) -> str:
        if self._api_key:
            return self._api_key
        provider_key = (llm_settings.get(provider, {}) or {}).get("api_key", "")
        if provider_key:
            return provider_key
        env_names = {
            "openai": ("OPENAI_API_KEY",),
            "openrouter": ("OPENROUTER_API_KEY",),
            "gemini": ("GEMINI_API_KEY", "GOOGLE_API_KEY"),
        }
        for name in env_names.get(provider, ()):
            value = os.environ.get(name)
            if value:
                return value
        return ""

    def _embedding_request_batch(self, texts: List[str]) -> List[List[float]]:
        if not texts:
            return []

        llm_settings, memory_settings = self._load_provider_settings()
        provider = llm_settings.get("provider", "gemini")

        if provider not in ("openai", "openrouter", "gemini"):
            raise ValueError(
                f"Long-term memory embeddings require OpenAI, OpenRouter, or Gemini provider, got {provider!r}"
            )

        api_key = self._get_key(llm_settings, provider)
        if not api_key:
            raise ValueError(f"No {provider} API key configured for memory embeddings")

        configured_model = memory_settings.get("embedding_model") or self._model
        if provider == "gemini":
            from google import genai
            from google.genai import types

            model = configured_model or "gemini-embedding-2"
            if model.startswith("google/"):
                model = model.split("/", 1)[1]
            client = genai.Client(api_key=api_key)
            try:
                response = client.models.embed_content(
                    model=model,
                    contents=texts,
                    config=types.EmbedContentConfig(output_dimensionality=self._full_dim),
                )
            except Exception:
                response = client.models.embed_content(model=model, contents=texts)
            if not response.embeddings or len(response.embeddings) != len(texts):
                raise ValueError("No embeddings returned from Gemini API")
            if any(not getattr(item, "values", None) for item in response.embeddings):
                raise ValueError("Gemini API returned an empty embedding")
            return [list(item.values) for item in response.embeddings]

        from openai import OpenAI

        if provider == "openrouter":
            base_url = "https://openrouter.ai/api/v1"
            model = configured_model or "openai/text-embedding-3-small"
            if "/" not in model:
                model = f"openai/{model}"
        else:
            openai_settings = llm_settings.get("openai", {}) or {}
            base_url = openai_settings.get("api_url", "").strip() or None
            model = configured_model or "text-embedding-3-small"
            if model.startswith("openai/"):
                model = model.split("/", 1)[1]

        client = OpenAI(api_key=api_key, base_url=base_url)
        try:
            response = client.embeddings.create(
                input=texts,
                model=model,
                dimensions=self._full_dim,
            )
        except Exception:
            response = client.embeddings.create(input=texts, model=model)

        data = list(response.data)
        if len(data) != len(texts):
            raise ValueError(
                f"Embedding API returned {len(data)} vectors for {len(texts)} inputs"
            )
        if all(isinstance(getattr(item, "index", None), int) for item in data):
            data.sort(key=lambda item: item.index)
            if [item.index for item in data] != list(range(len(texts))):
                raise ValueError("Embedding API returned invalid result indexes")
        return [list(item.embedding) for item in data]

    def _embedding_request(self, text: str) -> List[float]:
        return self._embedding_request_batch([text])[0]

    def _embed(self, text: str) -> EmbeddingResult:
        cache_key = self._cache_key(text)
        with self._cache_lock:
            cached = self._cache.get(cache_key)
        if cached is not None:
            return cached

        result = self._result_from_vector(self._embedding_request(text))
        with self._cache_lock:
            self._cache.set(cache_key, result)
        return result

    def embed_query(self, text: str) -> EmbeddingResult:
        return self._embed(text)

    def embed_document(self, text: str) -> EmbeddingResult:
        return self._embed(text)

    def embed_documents_batch(self, texts: List[str]) -> List[EmbeddingResult]:
        if not texts:
            return []

        results = [None] * len(texts)
        pending = {}
        for index, text in enumerate(texts):
            cache_key = self._cache_key(text)
            with self._cache_lock:
                cached = self._cache.get(cache_key)
            if cached is not None:
                results[index] = cached
                continue
            if cache_key not in pending:
                pending[cache_key] = {"text": text, "indexes": []}
            pending[cache_key]["indexes"].append(index)

        if pending:
            entries = list(pending.items())
            raw_vectors = self._embedding_request_batch(
                [entry["text"] for _, entry in entries]
            )
            if len(raw_vectors) != len(entries):
                raise ValueError(
                    f"Embedding API returned {len(raw_vectors)} vectors for "
                    f"{len(entries)} uncached inputs"
                )
            for (cache_key, entry), vector in zip(entries, raw_vectors):
                result = self._result_from_vector(vector)
                with self._cache_lock:
                    self._cache.set(cache_key, result)
                for index in entry["indexes"]:
                    results[index] = result

        if any(result is None for result in results):
            raise ValueError("Embedding batch did not produce every requested result")
        return results


# Backward-compatible name used by cognis.memory.
GeminiEmbedder = OpenAICompatibleEmbedder
